static int
format_decoder (const xtensa_insnbuf insn)
{
  if ((insn[0] & 0x8) == 0 && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 0; /* x24 */
  if ((insn[0] & 0xc) == 0x8 && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 1; /* x16a */
  if ((insn[0] & 0xe) == 0xc && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 2; /* x16b */
  if ((insn[0] & 0xe000001f) == 0xa000000f && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 3; /* ae_format_8 */
  if ((insn[0] & 0xe000001f) == 0xf && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 4; /* ae_format */
  if ((insn[0] & 0xe000003f) == 0x2000003f && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 5; /* ae_format_5 */
  if ((insn[0] & 0xe000001f) == 0x2000000f && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 6; /* ae_format_2 */
  if ((insn[0] & 0xe000003f) == 0x3f && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 7; /* ae_format_3 */
  if ((insn[0] & 0xe000001f) == 0x6000000f && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 8; /* ae_format_6 */
  if ((insn[0] & 0xe000001f) == 0x8000000f && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 9; /* ae_format_7 */
  if ((insn[0] & 0xe000001f) == 0xc000000f && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 10; /* ae_format_9 */
  if ((insn[0] & 0xe000001f) == 0xe000000f && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 11; /* ae_format_10 */
  if ((insn[0] & 0xe000001f) == 0x4000000f && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 12; /* ae_format_4 */
  if ((insn[0] & 0xf) == 0xe && (insn[1] & 0) == 0 && (insn[2] & 0) == 0 && (insn[3] & 0) == 0)
    return 13; /* ae_format_1 */
  return -1;
}

